    BufferedReader reader = new BufferedReader(new FileReader(file));
    String line;
    while ((line = reader.readLine()) != null) {
        // Parse the line to create a ThreadSnapshot
        // Assuming the format is "timestamp,threadId,snapshotData"
        String[] parts = line.split(",");
        long timestamp = Long.parseLong(parts[0]);
        int threadId = Integer.parseInt(parts[1]);
        String snapshotData = parts[2];

        // Check if the timestamp falls within any of the time ranges
        for (ProfileAnalyzeTimeRange range : timeRanges) {
            if (timestamp >= range.getStartTimestamp() && timestamp <= range.getEndTimestamp()) {
                ThreadSnapshot snapshot = new ThreadSnapshot(timestamp, threadId, snapshotData);
                threadSnapshots.add(snapshot);
                break;
            }
        }
    }
    reader.close();
    return threadSnapshots;
